  "Handy later for NHS reflections, scholarships and college essays.": "Utile plus tard pour les réflexions, les bourses et les candidatures.",
  "Organization": "Organisation",
  "The nonprofit or group you volunteered with — many schools require this on a verification form.": "L’association ou le groupe avec qui tu as fait du bénévolat — beaucoup d’écoles le demandent sur leur formulaire.",
  "Organization name": "Nom de l’organisation",
