  "123 Main St, Springfield, IL": "12 rue Principale, Lyon",
  "{place} isn't on your school's list of approved places. You can still log it, and your adviser will check it.": "{place} ne figure pas dans la liste des lieux approuvés de ton école. Tu peux quand même l’enregistrer : ton référent le vérifiera.",
  "Approved places:": "Lieux approuvés :",
  "and {n} more": "et {n} de plus",
  "Supervisor verification": "Vérification par un responsable",
  "Capture who can vouch for this work. Schools typically require a name and email.": "Indique qui peut confirmer ce travail. Les écoles demandent souvent un nom et un e-mail.",
  "Supervisor name": "Nom du responsable",
  "Mr. Johnson": "M. Martin",
  "Supervisor email": "E-mail du responsable",
  "johnson@school.edu": "martin@ecole.fr",
  "Supervisor mobile (optional)": "Mobile du responsable (facultatif)",
  "(555) 123-4567": "06 12 34 56 78",
  "We also text them the link. Good for supervisors who don’t check email. The number is deleted after 30 days.": "Nous lui envoyons aussi le lien par SMS, pratique pour ceux qui ne lisent pas leurs e-mails. Le numéro est supprimé au bout de 30 jours.",
  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer} vérifie et signe cela sur sa page Mes missions dans VolunTrack — aucun e-mail n’est envoyé.",
  "The task organizer": "L’organisateur de la mission",
  "Your supervisor will get an email with a link to review these hours. If they approve, they'll sign right there to confirm it — if they reject, no signature is needed. This usually takes a day or two.": "Ton responsable recevra un e-mail avec un lien pour vérifier ces heures. S’il les approuve, il signera directement ; s’il les refuse, aucune signature n’est nécessaire. Cela prend généralement un jour ou deux.",
  "Supervisor signature": "Signature du responsable",
  "Add your supervisor’s name — they’ll sign under Signatures below.": "Ajoute le nom de ton responsable : il signera sous Signatures plus bas.",
  "Supervisor name and email are required so this entry can be verified.": "Le nom et l’e-mail du responsable sont obligatoires pour que cette entrée puisse être vérifiée.",
  "Add a supervisor to have this entry verified — optional at your school.": "Ajoute un responsable pour faire vérifier cette entrée — facultatif dans ton école.",
  "Your school’s form": "Le formulaire de ton école",
  "Signatures": "Signatures",
  "will sign this on their My Tasks page — nothing to send.": "signera cela sur sa page Mes missions — rien à envoyer.",
  "They’re next to me now — have them sign here instead": "Il est à côté de moi — le faire signer ici",
  "Organizer signature *": "Signature de l’organisateur *",
