  "Language": "Langue",
  "Other language…": "Autre langue…",
  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "Ouvre VolunTrack dans le navigateur de ton téléphone (Chrome ou Safari) avec le bouton ci-dessous, et connecte-toi.",
  "Then use the browser’s translate, as shown below.": "Puis utilise la traduction du navigateur, comme ci-dessous.",
  "Use VolunTrack in another language": "Utiliser VolunTrack dans une autre langue",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "VolunTrack est disponible en anglais, espagnol, vietnamien et chinois, et ses écrans principaux en hindi, arabe, portugais, français, bengali, russe et japonais. Pour toute autre langue, ton navigateur peut traduire la page. C’est gratuit et cela fonctionne pour plus de 100 langues, comme le tagalog, le coréen, le créole haïtien, l’allemand et l’ourdou.",
  "computer": "ordinateur",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "Fais un clic droit n’importe où sur la page, choisis Traduire en…, puis ta langue.",
  "Android phone": "Téléphone Android",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "Touche ⋮ (en haut à droite), puis Traduire…, puis choisis ta langue.",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "Touche le menu de la page (aA ou l’icône à gauche de la barre d’adresse), puis Traduire en….",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "Clique sur l’icône de traduction dans la barre d’adresse, ou choisis Présentation → Traduction.",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "La traduction est faite par ton navigateur, pas par VolunTrack, et peut ne pas être parfaite. Les e-mails arrivent toujours en anglais ou dans la langue VolunTrack choisie.",
  "Open in browser": "Ouvrir dans le navigateur",
  "Got it": "Compris",
  "Default": "Par défaut",
  "Large": "Grand",
