  "Accessibility": "Accessibilité",
  "Make VolunTrack easier to read. These settings are saved on this device only.": "Rends VolunTrack plus facile à lire. Ces réglages sont enregistrés sur cet appareil uniquement.",
  "Brighter text, stronger borders and focus outlines, and underlined links.": "Texte plus lumineux, bordures et contours de focus plus marqués, liens soulignés.",
  "A font that keeps similar letters like I, l and 1 easy to tell apart. Can help with dyslexia or low vision.": "Une police qui distingue bien les lettres semblables comme I, l et 1. Peut aider en cas de dyslexie ou de basse vision.",
  "The short version": "La version courte",
  "The full": "Les",
  "are what count.": "complètes font foi.",
