  "Admin": "Admin",
  "Tasks": "Missions",
  "School": "École",
  "Your hours and details are shared only with the school or organization you join, parents you link, and organizers of events you sign up for. We never sell your data or show ads.": "Tes heures et informations ne sont partagées qu’avec l’école ou l’organisation que tu rejoins, les parents que tu lies et les organisateurs des événements auxquels tu t’inscris. Nous ne vendons jamais tes données et n’affichons pas de publicité.",
  "Log only hours you really did. Never sign for someone else or check in or out for them. False hours can get your account suspended.": "N’enregistre que les heures que tu as vraiment faites. Ne signe jamais pour quelqu’un d’autre et ne pointe jamais à sa place. Des heures fausses peuvent entraîner la suspension de ton compte.",
  "If you are under 13, a parent or guardian must approve your account.": "Si tu as moins de 13 ans, un parent ou tuteur doit approuver ton compte.",
  "Event organizers run their own events and keep volunteers safe; VolunTrack doesn't supervise them.": "Les organisateurs gèrent leurs propres événements et assurent la sécurité des bénévoles ; VolunTrack ne les supervise pas.",
  "You can delete your account at any time in Settings, and your data is deleted with it.": "Tu peux supprimer ton compte à tout moment dans Paramètres, et tes données sont supprimées avec lui.",
  "If these terms change, we will show you what changed and ask you to agree again.": "Si ces conditions changent, nous te montrerons ce qui a changé et te demanderons de les accepter à nouveau.",
  "You see students' hours, documents and progress only to review and verify their service. Keep them private and use them for nothing else.": "Tu vois les heures, documents et progrès des élèves uniquement pour vérifier leur service. Garde-les confidentiels et ne les utilise pour rien d’autre.",
  "Paid school and organization accounts are billed by invoice; until a payment is verified, some tools may be paused. A free club stays free.": "Les comptes école et organisation payants sont facturés ; tant qu’un paiement n’est pas vérifié, certains outils peuvent être suspendus. Un club gratuit reste gratuit.",
  "Approve or sign hours only when you believe they are right.": "N’approuve ou ne signe des heures que si tu penses qu’elles sont justes.",
  "We never sell anyone's data or show ads. Students, parents and volunteers keep their own free accounts.": "Nous ne vendons jamais les données de personne et n’affichons pas de publicité. Élèves, parents et bénévoles gardent leur propre compte gratuit.",
  "Your hours and details are shared only with the school you join, parents you link, and organizers of events you sign up for. We never sell your data or show ads.": "Tes heures et informations ne sont partagées qu’avec l’école que tu rejoins, les parents que tu lies et les organisateurs des événements auxquels tu t’inscris. Nous ne vendons jamais tes données et n’affichons pas de publicité.",
  "Event organizers run their own events and keep volunteers safe; VolunTrack doesn't supervise them. Give honest answers when you sign up, like your age.": "Les organisateurs gèrent leurs propres événements et assurent la sécurité des bénévoles ; VolunTrack ne les supervise pas. Réponds honnêtement lors de l’inscription, par exemple sur ton âge.",
  "Parent accounts are for adults 18 and over, and are free.": "Les comptes parents sont réservés aux adultes de 18 ans ou plus et sont gratuits.",
  "You see your child's hours read-only, after your child shares their link code with you. You can't change their entries.": "Tu vois les heures de ton enfant en lecture seule, une fois qu’il t’a donné son code de liaison. Tu ne peux pas modifier ses entrées.",
  "Confirm or approve your child's hours and event sign-ups only when you know they are right.": "Ne confirme ou n’approuve les heures et inscriptions de ton enfant que si tu sais qu’elles sont justes.",
  "We never sell your data or show ads. You can delete your account at any time in Settings.": "Nous ne vendons jamais tes données et n’affichons pas de publicité. Tu peux supprimer ton compte à tout moment dans Paramètres.",
  "Volunteer Task Maker accounts are for adults 18 and over, and are free.": "Les comptes créateur de missions sont réservés aux adultes de 18 ans ou plus et sont gratuits.",
  "You run your events: keep the details accurate and up to date, and keep volunteers safe on the day. VolunTrack doesn't supervise events.": "Tu gères tes événements : garde les informations exactes et à jour, et assure la sécurité des bénévoles le jour J. VolunTrack ne supervise pas les événements.",
  "Use volunteers' names and contact details only to run your event, and add co-hosts only if you trust them.": "N’utilise les noms et coordonnées des bénévoles que pour organiser ton événement, et n’ajoute que des co-organisateurs de confiance.",
  "Share check-in PINs and codes only at the event, and sign hours only when you believe they are right.": "Ne partage les PIN et codes de pointage qu’à l’événement, et ne signe des heures que si tu penses qu’elles sont justes.",
  "Messages, photos and notes must be appropriate for young people. Reported posts can be removed.": "Les messages, photos et notes doivent convenir à des jeunes. Les publications signalées peuvent être retirées.",
  "We never sell anyone's data or show ads. If these terms change, we will show you what changed and ask you to agree again.": "Nous ne vendons jamais les données de personne et n’affichons pas de publicité. Si ces conditions changent, nous te montrerons ce qui a changé et te demanderons de les accepter à nouveau.",
  "You see your schools' students' hours and progress only to review and verify their service. Keep them private and use them for nothing else.": "Tu vois les heures et progrès des élèves de tes écoles uniquement pour vérifier leur service. Garde-les confidentiels et ne les utilise pour rien d’autre.",
  "Organization accounts are billed by invoice; until a payment is verified, some tools may be paused.": "Les comptes organisation sont facturés ; tant qu’un paiement n’est pas vérifié, certains outils peuvent être suspendus.",
  "Send partner sign-off links only to a partner's real contact, and approve or sign hours only when you believe they are right.": "N’envoie les liens de validation qu’au vrai contact d’un partenaire, et n’approuve ou ne signe des heures que si tu penses qu’elles sont justes.",
  "VolunTrack. All rights reserved.": "VolunTrack. Tous droits réservés.",
  "Waking up the server — this can take up to a minute after a quiet spell.": "Réveil du serveur — cela peut prendre jusqu’à une minute après une période calme.",
  "Geolocation is not supported by your browser.": "La géolocalisation n’est pas prise en charge par votre navigateur.",
