  "\". Business names aren't always mapped yet — try the full street address instead, or tap \"Current\" to pin your exact location.": " ». Les noms d’entreprises ne sont pas toujours sur la carte — essaie l’adresse complète, ou touche « Actuelle » pour épingler ta position exacte.",
  "Not quite right? Drag the pin or click the map to adjust.": "Pas tout à fait ça ? Fais glisser l’épingle ou clique sur la carte pour ajuster.",
