  "This page hit an unexpected error. Your data is safe — try reloading.": "Cette page a rencontré une erreur inattendue. Tes données sont en sécurité — essaie de recharger.",
  "Reload": "Recharger",
  "Go home": "Accueil",
  "Welcome back to the volunteer dashboard.": "Bon retour sur le tableau de bord bénévole.",
  "Sign in and pick up where you left off—track hours, keep goals moving, and export your service record with confidence.": "Connecte-toi et reprends là où tu t’étais arrêté — suis tes heures, fais avancer tes objectifs et exporte ton relevé de bénévolat en toute confiance.",
  "Fast logging": "Saisie rapide",
  "Jump straight to the hours form and save every session with proof and supervisor details.": "Va directement au formulaire d’heures et enregistre chaque séance avec la preuve et les infos du superviseur.",
  "Progress tracking": "Suivi des progrès",
  "See goal completion, weekly activity, and earned badges in one clean view.": "Vois l’avancement de tes objectifs, ton activité de la semaine et tes badges en un seul coup d’œil.",
  "Need help getting started?": "Besoin d’aide pour commencer ?",
  "Create an account, set your first goal, and log your first volunteer hours to earn a badge.": "Crée un compte, fixe ton premier objectif et enregistre tes premières heures pour gagner un badge.",
  "Secure sign in": "Connexion sécurisée",
