  "PIN confirmation does not match.": "La confirmation du PIN ne correspond pas.",
  "PIN reset complete": "PIN réinitialisé",
  "Your new PIN has been saved. Return to login and unlock with your 4-digit PIN.": "Ton nouveau PIN est enregistré. Retourne à la connexion et déverrouille avec ton PIN à 4 chiffres.",
  "Reset your PIN": "Réinitialiser ton PIN",
  "We’ll email a PIN recovery code to confirm it’s really you.": "Nous t’enverrons par e-mail un code de récupération du PIN pour confirmer que c’est bien toi.",
  "The recovery server is up, but SMTP isn’t configured. Add": "Le serveur de récupération fonctionne, mais SMTP n’est pas configuré. Ajoute",
  ". For now, the PIN recovery code will appear on screen so you can finish.": ". En attendant, le code de récupération du PIN s’affichera à l’écran pour que tu puisses terminer.",
  "Send PIN recovery code": "Envoyer le code de récupération du PIN",
