  "A PIN recovery code has been sent to": "Un code de récupération du PIN a été envoyé à",
  "This deployment is a static site, so there’s no email server reachable from here. The PIN recovery code is shown below — only you can see this screen.": "Ce déploiement est un site statique, aucun serveur d’e-mail n’est donc joignable d’ici. Le code de récupération du PIN est affiché ci-dessous — toi seul peux voir cet écran.",
  ". Use the code below to continue — only you can see this screen.": ". Utilise le code ci-dessous pour continuer — toi seul peux voir cet écran.",
