  "References": "Recommandations",
  "Ask a supervisor or organizer who saw you volunteer to write a few lines about it, for college and scholarship applications. They get an email link and don’t need an account.": "Demande à un superviseur ou organisateur qui t’a vu faire du bénévolat d’écrire quelques lignes, pour tes candidatures universitaires et de bourses. Il reçoit un lien par e-mail et n’a pas besoin de compte.",
