  "1 task has no map location.": "1 mission n’a pas d’emplacement sur la carte.",
  "{n} tasks have no map location.": "{n} missions n’ont pas d’emplacement sur la carte.",
  "See them in the list": "Les voir dans la liste",
  "Goal reached": "Objectif atteint",
  "You met your requirement!": "Tu as rempli ton exigence !",
  "You reached your goal!": "Tu as atteint ton objectif !",
  "{hours} logged. That’s everything {school} asks for.": "{hours} enregistrées. C’est tout ce que demande {school}.",
