  "Manage reminders": "Gérer les rappels",
  "Privacy": "Confidentialité",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "Tes heures sont stockées sur cet appareil. Si tu as créé un compte, certaines fonctions ci-dessus (partage familial, lien avec l’établissement, synchro entre appareils, double authentification) stockent aussi des données sur notre serveur. Déconnecte-toi ci-dessous pour effacer ta session.",
