  "Delete account": "Supprimer le compte",
  "Remove your account and your VolunTrack data — from this device and, if you have an account with us, from our servers too. This action cannot be undone.": "Supprime ton compte et tes données VolunTrack — de cet appareil et, si tu as un compte chez nous, de nos serveurs aussi. Cette action est irréversible.",
  "Confirm account deletion": "Confirmer la suppression du compte",
