  "Passkey removed.": "Clé d’accès retirée.",
  "Passkeys": "Clés d’accès",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "Après ton mot de passe, confirme ton identité avec Face ID, Touch ID, ton empreinte ou le code de ton appareil au lieu de taper un code. Garde aussi ton application d’authentification — ses codes de secours te permettent de revenir si tu perds tous les appareils avec une clé d’accès.",
