  "Loading requirements…": "Chargement des exigences…",
  "Schools you assign to this template follow these sections instead of your defaults. A section left unset here uses your defaults, and a school can still set its own.": "Les établissements que tu assignes à ce modèle suivent ces sections au lieu de tes valeurs par défaut. Une section non définie ici utilise tes valeurs par défaut, et un établissement peut toujours définir la sienne.",
  "Every rule here applies to the students linked to your school. Anything you leave inherited follows your organization, or VolunTrack’s defaults if you have none.": "Chaque règle ici s’applique aux élèves liés à ton établissement. Ce que tu laisses hérité suit ton organisation, ou les valeurs par défaut de VolunTrack si tu n’en as pas.",
  "These are the defaults for every school you own. A school that sets its own version of a section keeps it — your changes reach the rest.": "Ce sont les valeurs par défaut de chaque établissement que tu possèdes. Un établissement qui définit sa propre version d’une section la garde — tes changements s’appliquent aux autres.",
  "Inherit": "Hériter",
  "Set our own": "Définir nos propres règles",
  "Set in this template": "Défini dans ce modèle",
  "Set a default": "Définir une valeur par défaut",
  "Save requirements": "Enregistrer les exigences",
  "Require a proof file": "Exiger un fichier de preuve",
  "Require a supervisor name and email": "Exiger le nom et l’e-mail d’un superviseur",
  "Require a location": "Exiger un lieu",
  "Require the organization name": "Exiger le nom de l’organisation",
  "Allow future-dated entries": "Autoriser les entrées datées dans le futur",
  "Minimum hours per entry": "Heures minimum par entrée",
  "No minimum": "Pas de minimum",
  "Maximum hours per entry": "Heures maximum par entrée",
  "Maximum hours on one day": "Heures maximum sur une journée",
  "Log within N days of the activity": "Enregistrer dans les N jours suivant l’activité",
  "Any time after": "N’importe quand après",
  "Minimum description length": "Longueur minimale de la description",
  "Students can’t add, edit or delete entries dated before this, e.g. once a semester’s report is done. You can still add hours for them.": "Les élèves ne peuvent pas ajouter, modifier ni supprimer des entrées datées d’avant, ex. une fois le rapport du semestre bouclé. Tu peux toujours ajouter des heures pour eux.",
  "Allowed categories": "Catégories autorisées",
  "Leave all unchecked to accept every category.": "Laisse tout décoché pour accepter toutes les catégories.",
  "Approved places": "Lieux approuvés",
  "One per line. Hours from anywhere else still go in, but they're flagged in Students → Hours to check so you can look at them first. Leave empty to accept every place.": "Un par ligne. Les heures faites ailleurs sont acceptées, mais signalées dans Élèves → Heures à vérifier pour que tu les regardes d’abord. Laisse vide pour accepter tous les lieux.",
  "Total hours required": "Total d’heures exigé",
  "None": "Aucun",
  "Deadline": "Échéance",
  "Grades at your school": "Classes de ton établissement",
  "Tick the grades you have, e.g. only 9th, or 10th–12th. Students then pick from these, must pick one to join, and “New school year” moves your top grade on. Leave all unticked to allow any grade.": "Coche les classes que tu as, ex. seulement la 3e, ou de la 2de à la terminale. Les élèves choisissent alors parmi celles-ci, doivent en choisir une pour rejoindre, et « Nouvelle année scolaire » fait passer ta classe la plus haute. Laisse tout décoché pour autoriser toutes les classes.",
  "Note to students": "Note aux élèves",
  "Due before senior year begins.": "À rendre avant le début de la terminale.",
  "Per-grade overrides": "Exceptions par classe",
  "A student in one of these grades is held to its number instead of the total above.": "Un élève de l’une de ces classes doit atteindre ce nombre au lieu du total ci-dessus.",
  "Minimum hours by type": "Heures minimum par type",
  "At least this many of a student’s hours must be of one type. They count toward the total, not on top of it.": "Au moins ce nombre d’heures d’un élève doit être d’un type donné. Elles comptent dans le total, pas en plus.",
  "Add a type": "Ajouter un type",
  "+ Add a type…": "+ Ajouter un type…",
  "Grade (e.g. 11, Junior, Year 12)": "Classe (ex. 11, Première, Year 12)",
  "Students must sign in with our school account (SSO)": "Les élèves doivent se connecter avec le compte de notre établissement (SSO)",
  "Allowed email domains": "Domaines e-mail autorisés",
  "No levels yet.": "Aucun niveau pour l’instant.",
  "Use Bronze, Silver, Gold": "Utiliser Bronze, Argent, Or",
  "Level name": "Nom du niveau",
  "Add a level": "Ajouter un niveau",
  "Hours count the same way as your requirement: everything logged except rejected entries.": "Les heures se comptent comme pour ton exigence : tout ce qui est enregistré sauf les entrées refusées.",
  "New signer: the old signature was removed. Draw theirs below, or use the phone QR code.": "Nouveau signataire : l’ancienne signature a été retirée. Dessine la sienne ci-dessous, ou utilise le QR code téléphone.",
  "What each entry needs": "Ce que chaque entrée exige",
  "Who signs": "Qui signe",
  "Students sign on the Log Hours form before they can save.": "Les élèves signent dans le formulaire Enregistrer des heures avant de pouvoir enregistrer.",
  "Students must name a supervisor, who gets an emailed link and signs there to approve.": "Les élèves doivent indiquer un superviseur, qui reçoit un lien par e-mail et y signe pour approuver.",
  "Students sign on the form, and their supervisor signs on the emailed link to approve.": "Les élèves signent dans le formulaire, et leur superviseur signe via le lien reçu par e-mail pour approuver.",
  "Link to your form": "Lien vers ton formulaire",
  "Google Form — students fill it in right on the Log Hours page, then tick a box to say they sent it.": "Google Form — les élèves le remplissent directement sur la page Enregistrer des heures, puis cochent une case pour dire qu’ils l’ont envoyé.",
  "A Google Form opens right on the Log Hours page. Any other link (a PDF, a doc) is something students download, get signed, and upload. Leave blank if they get the form in class.": "Un Google Form s’ouvre directement sur la page Enregistrer des heures. Tout autre lien (un PDF, un document) est à télécharger, faire signer et renvoyer par les élèves. Laisse vide s’ils reçoivent le formulaire en classe.",
  "This looks like the link for editing the form. Use Send → link in Google Forms instead, so students can fill it in.": "Cela ressemble au lien de modification du formulaire. Utilise plutôt Envoyer → lien dans Google Forms, pour que les élèves puissent le remplir.",
  "Short forms.gle links can’t open inside VolunTrack. Paste the full docs.google.com link to keep students on the page.": "Les liens courts forms.gle ne s’ouvrent pas dans VolunTrack. Colle le lien complet docs.google.com pour garder les élèves sur la page.",
  "Note to students (optional)": "Note aux élèves (facultatif)",
  "Your supervisor must sign in blue or black ink.": "Ton superviseur doit signer à l’encre bleue ou noire.",
  "Question": "Question",
  "Advisor name": "Nom du conseiller",
  "Answer type": "Type de réponse",
  "Choices": "Choix",
  "First period, Second period, Third period": "Première heure, Deuxième heure, Troisième heure",
  "Comma-separated. A question with no choices is dropped when you save.": "Séparés par des virgules. Une question sans choix est supprimée à l’enregistrement.",
  "Helper text (optional)": "Texte d’aide (facultatif)",
  "Required": "Obligatoire",
