  "Loading branding…": "Chargement de l’image de marque…",
  "Accent colour": "Couleur d’accent",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "Une valeur hexadécimale. Utilisée pour les accents de ta page de connexion — pas pour le texte ni le fond des boutons, donc toute couleur reste lisible. Laisse vide pour le vert VolunTrack.",
  "Enter a hex value like #2f855a.": "Saisis une valeur hexadécimale comme #2f855a.",
  "Preview": "Aperçu",
  "Save branding": "Enregistrer l’image de marque",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "Cette image de marque s’applique aux noms d’hôte de ton organisation. Chaque établissement gère la sienne séparément.",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "Seule la page de connexion de ton établissement change. Le nom et le logo VolunTrack restent sur le site principal.",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "L’image de marque n’apparaît que sur ton propre nom d’hôte. Tu n’as pas encore de domaine actif — configure-en un dans Domaine personnalisé, puis ce que tu enregistres ici s’affichera sur sa page de connexion.",
  "Shown at sign-in on": "Affiché à la connexion sur",
