  "Say why, so the student can fix it.": "Explique pourquoi, pour que l’élève puisse corriger.",
  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "Entrées qu’aucun superviseur ni organisateur n’a confirmées. Elles comptent pour l’instant ; approuve-les, ou renvoies-en une avec un motif et elle ne compte plus jusqu’à ce que l’élève la corrige.",
