  "Showing 25 of {n}. The exports contain every student.": "Affichage de 25 sur {n}. Les exports contiennent tous les élèves.",
  "Loading domains…": "Chargement des domaines…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "Les domaines personnalisés peuvent être revendiqués et vérifiés, mais ce serveur ne peut pas encore émettre de certificats : un domaine ne peut donc pas être mis en ligne. Contacte le support VolunTrack.",
