  "Move every student up a grade at the start of the year. 12th graders become Graduated. You can undo it for {n} days.": "Fais passer chaque élève en classe supérieure en début d’année. Les terminales deviennent Diplômés. Tu peux annuler pendant {n} jours.",
  "Last moved up on {date} (1 student).": "Dernier passage le {date} (1 élève).",
