  "Partner organizations": "Organisations partenaires",
  "The nonprofits your schools work with, kept in one list. Students at your schools see it on Opportunities, and advisers also see the contact person.": "Les associations avec lesquelles tes établissements travaillent, en une seule liste. Les élèves de tes établissements la voient dans Opportunités, et les référents voient aussi la personne de contact.",
