  "The organizer of an event {name} signed up for sees this on their check-in list, only around the day of the event. It isn’t shown anywhere else.": "L’organisateur d’un événement auquel {name} s’est inscrit le voit sur sa liste d’arrivée, seulement autour du jour de l’événement. Il n’est affiché nulle part ailleurs.",
