  "Kids your age have a small goal. Every little bit helps!": "Les enfants de ton âge ont un petit objectif. Chaque petit geste compte !",
  "New main admin": "Nouvel administrateur principal",
  "A parent must come with volunteers in 5th grade or younger": "Un parent doit accompagner les bénévoles jusqu’au CM2",
  "K–5th grade: parent comes too": "De la maternelle au CM2 : un parent vient aussi",
  "They’ll tell you which parent or guardian is coming when they sign up.": "Ils t’indiqueront quel parent ou tuteur vient en s’inscrivant.",
  "1 entry is saved on this device and waiting to send.": "1 entrée est enregistrée sur cet appareil et attend d’être envoyée.",
  "{n} entries are saved on this device and waiting to send.": "{n} entrées sont enregistrées sur cet appareil et attendent d’être envoyées.",
  "Couldn’t reach VolunTrack yet. It keeps trying by itself.": "Impossible de joindre VolunTrack pour l’instant. Il réessaie tout seul.",
  "They send by themselves when you’re back online.": "Elles s’envoient toutes seules quand tu es de nouveau en ligne.",
  "Send now": "Envoyer maintenant",
  "Saved on this device. It sends by itself when you’re back online.": "Enregistrée sur cet appareil. Elle s’envoie toute seule quand tu es de nouveau en ligne.",
  "Waiting to send": "En attente d’envoi",
  "Could not make the packet.": "Impossible de créer le dossier.",
  "End-of-year packet": "Dossier de fin d’année",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "Un ZIP avec un dossier par établissement : récapitulatif, toutes les entrées et le rapport d’heures de chaque élève.",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "Un ZIP avec le récapitulatif, toutes les entrées, l’historique des validations, les certificats des élèves qui ont atteint l’exigence et le rapport d’heures de chaque élève.",
  "School year": "Année scolaire",
  "Making student reports… {done} of {total}": "Création des rapports élèves… {done} sur {total}",
  "Making the packet…": "Création du dossier…",
  "Download packet": "Télécharger le dossier",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "L’année scolaire va du 1er août au 31 juillet. Le ZIP contient des informations personnelles d’élèves, garde-le en lieu sûr.",
  "A parent or guardian must come with you to this event. Who is coming? (their name)": "Un parent ou tuteur doit venir avec toi à cet événement. Qui vient ? (son nom)",
  "Parent coming: {name}": "Parent présent : {name}",
