  "When I'm free": "Quand je suis libre",
  "Edit when you are free": "Modifier tes disponibilités",
  "When are you usually free?": "Quand es-tu généralement libre ?",
  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "Coche les moments qui te conviennent. « Quand je suis libre » n’affiche alors que les événements qui commencent à ces moments-là. Toi seul vois ceci.",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "Le matin, c’est avant midi, l’après-midi de midi à 17 h, le soir après 17 h.",
  "Could not save when you are free.": "Impossible d’enregistrer tes disponibilités.",
