  "Emailed to {email}.": "Envoyé à {email}.",
  "Copy this link to them:": "Copie-lui ce lien :",
  "{n} entries waiting. Works for {days} days; a new link replaces this one.": "{n} entrées en attente. Valable {days} jours ; un nouveau lien remplace celui-ci.",
