  "Leaving? Check out": "Tu pars ? Enregistre ton départ",
  "Checked in at {time}. Type the check-out PIN the organizer gives you.": "Arrivé à {time}. Tape le PIN de départ que te donne l’organisateur.",
  "Check-out PIN": "PIN de départ",
