  "Only their clubs": "Seulement ses clubs",
  "They see only students in the clubs they advise: student list, hours to check, progress and reports.": "Il ne voit que les élèves des clubs qu’il encadre : liste d’élèves, heures à vérifier, progression et rapports.",
  "Assignments": "Devoirs",
  "New assignment": "Nouveau devoir",
