  "Switching from x2VOL, MobileServe or a spreadsheet? Upload a CSV with student email, date, activity and hours (organization, category and notes are optional). Hours come in approved, for students already at your school.": "Tu viens de x2VOL, MobileServe ou d’un tableur ? Envoie un CSV avec l’e-mail de l’élève, la date, l’activité et les heures (organisation, catégorie et notes facultatives). Les heures arrivent approuvées, pour les élèves déjà dans ton établissement.",
