  "On. Students who join see a top-10 of your school by approved hours (first name and last initial only). Under-13s never appear.": "Activé. Les élèves qui le rejoignent voient un top 10 de ton établissement par heures approuvées (prénom et initiale seulement). Les moins de 13 ans n’apparaissent jamais.",
