  "Your tasks": "Tes missions",
  "Guests of approved volunteers": "Invités des bénévoles approuvés",
  "Show-up rate counts volunteers you approved who were marked present or checked in, out of those plus anyone marked absent. Excused volunteers and anyone not yet marked aren't counted. Hours are approved hours logged on the task.": "Le taux de présence compte les bénévoles approuvés marqués présents ou arrivés, sur ceux-ci plus les absents. Les excusés et ceux non encore marqués ne comptent pas. Les heures sont les heures approuvées enregistrées sur la mission.",
  "QR code to sign on a phone": "QR code pour signer sur un téléphone",
  "Fall": "Automne",
  "Spring": "Printemps",
  "Term goals": "Objectifs par période",
  "Split the year into terms, each with its own hours. Students see this term’s progress, and you see who is behind this term. Hours count toward the term they were logged in.": "Divise l’année en périodes, chacune avec ses heures. Les élèves voient leur progression de la période en cours, et toi qui est en retard. Les heures comptent pour la période où elles ont été enregistrées.",
