  "Love VolunTrack?": "Tu aimes VolunTrack ?",
  "You've logged your first volunteer session. We'd love to hear how it's going for you!": "Tu as enregistré ta première séance de bénévolat. Nous aimerions savoir comment ça se passe pour toi !",
  "Rate your experience": "Note ton expérience",
