  "Volunteers signed up": "Bénévoles inscrits",
  "Fill in shift lengths": "Remplir les durées des créneaux",
  "My Students": "Mes élèves",
  "No approved students yet — approve a signup above to see them here.": "Aucun élève approuvé pour l’instant — approuve une inscription ci-dessus pour les voir ici.",
  "No logged hours yet.": "Aucune heure enregistrée pour l’instant.",
  "Signed & approved": "Signé et approuvé",
