  "Waiver (optional)": "Décharge (facultatif)",
  "Paste your organization's waiver or release. Volunteers agree by typing their name; for anyone under 18, a parent or guardian agrees too.": "Colle la décharge ou l’autorisation de ton organisation. Les bénévoles acceptent en tapant leur nom ; pour les moins de 18 ans, un parent ou tuteur accepte aussi.",
  "Thank you": "Merci",
  "Almost done. Pick your account type and fill in the rest. You won’t need a password: sign in with the same button next time.": "Presque fini. Choisis ton type de compte et remplis le reste. Pas besoin de mot de passe : connecte-toi avec le même bouton la prochaine fois.",
  "Log some hours first, then make your résumé.": "Enregistre d’abord quelques heures, puis crée ton CV.",
  "Download résumé": "Télécharger le CV",
