  "Verification": "Vérification",
  "Found a bug, have a feature request, or just want to say hi? We'd love to hear from you.": "Tu as trouvé un bug, une idée de fonctionnalité, ou tu veux juste dire bonjour ? Nous serions ravis d’avoir de tes nouvelles.",
  "Check that a VolunTrack transcript is genuine and has not been changed since it was issued. No account needed. The file is checked by our server and not stored.": "Vérifie qu’un relevé VolunTrack est authentique et n’a pas été modifié depuis son émission. Pas besoin de compte. Le fichier est vérifié par notre serveur et n’est pas conservé.",
