  "People who didn’t sign up can scan this code to join and check in, while there are spots left.": "Les personnes non inscrites peuvent scanner ce code pour rejoindre et arriver, tant qu’il reste des places.",
  "Join as a walk-in?": "Rejoindre sans inscription ?",
  "You didn’t sign up for {title}. Join now and check in, and your hours go to the organizer to sign.": "Tu ne t’es pas inscrit à {title}. Rejoins maintenant et enregistre ton arrivée, et tes heures iront à l’organisateur pour signature.",
  "Join and check in": "Rejoindre et arriver",
  "I didn’t sign up": "Je ne me suis pas inscrit",
