  "On my phone": "Sur mon téléphone",
  "Scan the code on this screen with your phone’s camera and tap Join and check in.": "Scanne le code de cet écran avec l’appareil photo de ton téléphone et touche Rejoindre et arriver.",
  "Here, with the organizer": "Ici, avec l’organisateur",
  "No phone? The organizer types your VolunTrack email and checks you in.": "Pas de téléphone ? L’organisateur tape ton e-mail VolunTrack et enregistre ton arrivée.",
  "Add a walk-in": "Ajouter une personne sans inscription",
  "Type the email they use for VolunTrack.": "Tape l’e-mail qu’il utilise pour VolunTrack.",
