  "Remember it. When you leave, tap your name here and type this PIN to check out.": "Retiens-le. En partant, touche ton nom ici et tape ce PIN pour enregistrer ton départ.",
  "I’ll remember it": "Je m’en souviendrai",
  "Volunteer of the month": "Bénévole du mois",
  "Give one student a shout-out. They and their parents get a notification and a certificate. Only they and your school see it.": "Mets un élève à l’honneur. Lui et ses parents reçoivent une notification et un certificat. Seuls eux et ton établissement le voient.",
  "Choose a student": "Choisis un élève",
  "Why? (optional, they will see it)": "Pourquoi ? (facultatif, il le verra)",
  "Give shout-out": "Mettre à l’honneur",
  "Earlier:": "Précédemment :",
  "Could not save volunteer of the month.": "Impossible d’enregistrer le bénévole du mois.",
  "Undo this month’s volunteer of the month?": "Annuler le bénévole du mois de ce mois-ci ?",
  "You're volunteer of the month! 🌟": "Tu es le bénévole du mois ! 🌟",
  "{school} picked you for {month}.": "{school} t’a choisi pour {month}.",
  "1 student is behind and hasn't logged anything in {n} days.": "1 élève est en retard et n’a rien enregistré depuis {n} jours.",
